// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity =0.7.6;
pragma abicoder v2;

import "../core/interfaces/ICLPool.sol";
import "./libraries/uniswap/SafeERC20Namer.sol";
import "./libraries/base64-sol/base64.sol";

import "./libraries/ChainId.sol";
import "./interfaces/INonfungiblePositionManager.sol";
import "./interfaces/INonfungibleTokenPositionDescriptor.sol";
import "./interfaces/IERC20Metadata.sol";
import "./libraries/PoolAddress.sol";
import "./libraries/NFTDescriptor.sol";
import "./libraries/TokenRatioSortOrder.sol";
import "./libraries/NFTSVG.sol";

/// @title Describes NFT token positions
/// @notice Produces a string containing the data URI for a JSON metadata string
contract NonfungibleTokenPositionDescriptor is
    INonfungibleTokenPositionDescriptor
{
    // Mezo mainnet token addresses
    address private constant MUSD = 0xdD468A1DDc392dcdbEf6db6e34E89AA338F9F186;
    address private constant MUSDC = 0x04671C72Aab5AC02A03c1098314b1BB6B560c197;
    address private constant MUSDT = 0xeB5a5d39dE4Ea42C2Aa6A57EcA2894376683bB8E;
    address private constant MEZO = 0x7B7c000000000000000000000000000000000001;
    address private constant BTC = 0x7b7C000000000000000000000000000000000000;

    /// @inheritdoc INonfungibleTokenPositionDescriptor
    function tokenURI(
        INonfungiblePositionManager positionManager,
        uint256 tokenId
    ) external view override returns (string memory) {
        (
            ,
            ,
            address token0,
            address token1,
            int24 tickSpacing,
            int24 tickLower,
            int24 tickUpper,
            ,
            ,
            ,
            ,

        ) = positionManager.positions(tokenId);

        ICLPool pool = ICLPool(
            PoolAddress.computeAddress(
                positionManager.factory(),
                PoolAddress.PoolKey({
                    token0: token0,
                    token1: token1,
                    tickSpacing: tickSpacing
                })
            )
        );

        bool _flipRatio = flipRatio(token0, token1, ChainId.get());
        address quoteTokenAddress = !_flipRatio ? token1 : token0;
        address baseTokenAddress = !_flipRatio ? token0 : token1;
        NFTDescriptor.ConstructTokenURIParams memory params = NFTDescriptor
            .ConstructTokenURIParams({
                tokenId: tokenId,
                quoteTokenAddress: quoteTokenAddress,
                baseTokenAddress: baseTokenAddress,
                quoteTokenSymbol: SafeERC20Namer.tokenSymbol(quoteTokenAddress),
                baseTokenSymbol: SafeERC20Namer.tokenSymbol(baseTokenAddress),
                quoteTokenDecimals: IERC20Metadata(quoteTokenAddress)
                    .decimals(),
                baseTokenDecimals: IERC20Metadata(baseTokenAddress).decimals(),
                flipRatio: _flipRatio,
                tickLower: tickLower,
                tickUpper: tickUpper,
                tickSpacing: tickSpacing,
                poolAddress: address(pool)
            });

        string memory image = Base64.encode(
            bytes(generateSVG(positionManager, params))
        );

        string memory nameAndDescription = NFTDescriptor.constructTokenURI(
            params
        );

        return
            string(
                abi.encodePacked(
                    "data:application/json;base64,",
                    Base64.encode(
                        bytes(
                            abi.encodePacked(
                                "{",
                                nameAndDescription,
                                ", 'image': '",
                                "data:image/svg+xml;base64,",
                                image,
                                "'}"
                            )
                        )
                    )
                )
            );
    }

    function generateSVG(
        INonfungiblePositionManager positionManager,
        NFTDescriptor.ConstructTokenURIParams memory params
    ) internal view returns (string memory) {
        (uint256 quoteTokensOwed, uint256 baseTokensOwed) = tokensOwed({
            positionManager: positionManager,
            tokenId: params.tokenId,
            _flipRatio: params.flipRatio
        });
        return
            NFTSVG.generateSVG({
                quoteTokenSymbol: params.quoteTokenSymbol,
                baseTokenSymbol: params.baseTokenSymbol,
                quoteTokensOwed: quoteTokensOwed,
                baseTokensOwed: baseTokensOwed,
                tokenId: params.tokenId,
                tickLower: params.tickLower,
                tickUpper: params.tickUpper,
                tickSpacing: params.tickSpacing,
                quoteTokenDecimals: params.quoteTokenDecimals,
                baseTokenDecimals: params.baseTokenDecimals
            });
    }

    function tokensOwed(
        INonfungiblePositionManager positionManager,
        uint256 tokenId,
        bool _flipRatio
    ) internal view returns (uint256 quoteTokensOwed, uint256 baseTokensOwed) {
        (
            ,
            ,
            ,
            ,
            ,
            ,
            ,
            ,
            ,
            ,
            uint256 tokensOwed0,
            uint256 tokensOwed1
        ) = positionManager.positions(tokenId);
        quoteTokensOwed = _flipRatio ? tokensOwed1 : tokensOwed0;
        baseTokensOwed = _flipRatio ? tokensOwed0 : tokensOwed1;
    }

    function flipRatio(
        address token0,
        address token1,
        uint256 chainId
    ) public view returns (bool) {
        return
            tokenRatioPriority(token0, chainId) >
            tokenRatioPriority(token1, chainId);
    }

    function tokenRatioPriority(
        address token,
        uint256 chainId
    ) public view returns (int256) {
        // Using Mezo mainnet chain ID and token addresses.
        if (chainId == 31612) {
            if (token == MUSD) {
                return TokenRatioSortOrder.NUMERATOR_MOST;
            } else if (token == MUSDC) {
                return TokenRatioSortOrder.NUMERATOR_MORE;
            } else if (token == MUSDT) {
                return TokenRatioSortOrder.NUMERATOR;
            } else if (token == MEZO) {
                return TokenRatioSortOrder.DENOMINATOR;
            } else if (token == BTC) {
                return TokenRatioSortOrder.DENOMINATOR_MOST;
            } else {
                return 0;
            }
        }
        return 0;
    }
}
